  ('SRC-065', 'HelloAsso — Blog et pages d''événements associatifs', 'https://www.helloasso.com/blog/', 'communaute', 'verifie', '{"id":"SRC-065","name":"HelloAsso — Blog et pages d''événements associatifs","url":"https://www.helloasso.com/blog/","type":"communaute","sector_families":["communautaire","sport","universitaire"],"scale":"independants","language":"fr","country":"FR","cadence_suggeree":"hebdomadaire","notes":"Pages publiques d''événements (helloasso.com/associations/<asso>/evenements/...) pour repérer des formats locaux. Blog promotionnel. Ne jamais relever de données de participants ni d''organisateurs personnes physiques. Vérif. : domaine et rubrique confirmés par la recherche (page exacte non renvoyée).","verified_at":"2026-11-24","verification":"verifie"}'::jsonb),
