  ('SRC-067', 'Ulule', 'https://www.ulule.com/', 'communaute', 'verifie', '{"id":"SRC-067","name":"Ulule","url":"https://www.ulule.com/","type":"communaute","sector_families":["communautaire","musique_festival"],"scale":"independants","language":"fr","country":"FR","cadence_suggeree":"mensuelle","notes":"Campagnes de financement de festivals et d''événements : montant collecté = donnée plateforme ; promesses du porteur = déclaratif (D). Vérif. : domaine et rubrique confirmés par la recherche (page exacte non renvoyée).","verified_at":"2026-11-24","verification":"verifie"}'::jsonb),
  ('SRC-068', 'France 3 Régions', 'https://france3-regions.franceinfo.fr/', 'presse_generale', 'verifie', '{"id":"SRC-068","name":"France 3 Régions","url":"https://france3-regions.franceinfo.fr/","type":"presse_generale","sector_families":["communautaire","sport","musique_festival"],"scale":"independants","language":"fr","country":"FR","cadence_suggeree":"quotidienne","notes":"Antennes régionales : couverture d''événements locaux (rubriques par région, ex. /normandie/). Vérif. : domaine et rubrique confirmés par la recherche (page exacte non renvoyée).","verified_at":"2026-11-24","verification":"verifie"}'::jsonb),
  ('SRC-069', 'Google Actualités', 'https://news.google.com/', 'agregateur', 'verifie', '{"id":"SRC-069","name":"Google Actualités","url":"https://news.google.com/","type":"agregateur","sector_families":["sport","esport","musique_festival","communautaire"],"scale":"mixte","language":"fr","country":"INT","cadence_suggeree":"quotidienne","notes":"Pages « topics » pour repérer ; ne jamais citer l''agrégateur : remonter à l''article d''origine. Vérif. : domaine et rubrique confirmés par la recherche (page exacte non renvoyée).","verified_at":"2026-11-24","verification":"verifie"}'::jsonb),
