emaine 7 : vote du nom, des couleurs et du trophée. Semaine 8 : tournoi fondateur (12 équipes, une journée) et publication du règlement sous licence ouverte.","rules_summary":"La constitution interdit : contact au-dessus des épaules, objets durs lancés, équipements non disponibles en gymnase standard, matchs de plus de 20 min ; elle impose : mixité possible, variante assise ou adaptée. Une règle votée qui échoue au test de sécurité est remplacée par la proposition arrivée deuxième. Vote : gratuit, un par compte vérifié, résultats publics.","duration_hours":7,"edition_cadence":"programme annuel par ville ; inter-villes des sports inventés possible ensuite","building_blocks":[{"type":"interaction_public","label":"Votes hebdomadaires de modules de règles","parameters":{"modules":6,"propositions_par_module":3}},{"type":"regles","label":"Constitution de sécurité et d''inclusion non votable","parameters":{}},{"type":"mecanique_jeu","label":"Séances de test publiques et règle de repli","parameters":{"seances":6}},{"type":"creation_contenu","label":"Feuilleton vidéo hebdomadaire","parameters":{"episodes":8}},{"type":"experience_digitale","label":"Plateforme de vote et règlement évolutif en ligne","parameters":{}},{"type":"mise_en_scene","label":"Tournoi fondateur et « premier match officiel »","parameters":{"equipes":12}},{"type":"fidelisation","label":"Catalogue des sports inventés, inter-villes","parameters":{}},{"type":"monetisation","label":"Commande de la ville ou d''une marque","parameters":{}}]},"participants":{"unit":"equipe","count":{"prudent":8,"central":12,"ambitieux":16},"team_size":6,"categories":["mixte","variante adaptée"]},"audience":{"attendance":{"prudent":150,"central":300,"ambitieux":600},"paying_share":0,"avg_dwell_min":120},"venue_requirements":{"setting":"mixte","min_area_m2":800,"spaces":[{"id":"gymnase","type":"aire_de_jeu","label":"Gymnase pour les tests et le tournoi"},{"id":"public","type":"tribune"},{"id":"media","type":"media","label":"Coin captation et interviews"}],"power_kw":5,"internet":"plateforme de vote en ligne","notes":"La constitution limite le matériel à celui d''un gymnase standard pour que le sport soit reproductible."},"budget":{"currency":"EUR","contingency_rate":0.1,"expenses":[{"id":"e-community","category":"personnel","label":"Animation de communauté (8 semaines × 2 jours × 300 €)","amount":4800,"basis":"fixed","certainty":"hypothese","priority":1},{"id":"e-vote","category":"digital","label":"Plateforme de vote sans code","amount":300,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-tests","category":"materiel","label":"Matériel de test","amount":800,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-video","category":"media","label":"Feuilleton vidéo (8 épisodes × 400 €)","amount":3200,"basis":"fixed","certainty":"estimation","priority":2},{"id":"e-tournoi","category":"evenement","label":"Tournoi fondateur (son, écran, arbitrage, trophée, accueil)","amount":4000,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-securite","category":"securite","label":"Revue de sécurité des règles par un professionnel du sport","amount":600,"basis":"fixed","certainty":"hypothese","priority":1},{"id":"e-assurance","category":"assurance","label":"Assurance RC (tests et tournoi)","amount":400,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-coordination","category":"prestation","label":"Direction de programme EVENT LAB","amount":2000,"basis":"fixed","certainty":"hypothese","priority":1}],"revenues":[{"id":"r-commande","stream":"autre","label":"Commande de la ville ou d''une marque (signée avant lancement)","unit_amount":20000,"basis":"fixed","certainty":"secured"}]},"risks":[{"id":"R1","category":"securite","description":"Une règle votée crée un jeu dangereux (collisions, projectiles)","probability":3,"impact":4,"critical":true,"warning_signs":["blessures légères en séance de test"],"prevention":["constitution de sécurité non votable","revue par un professionnel du sport avant chaque test","test obligatoire avant adoption"],"continuity_plan":"Règle remplacée par la proposition arrivée deuxième ; séance de test supplémentaire","owner_role":"référent sécurité","status":"ouvert"},{"id":"R2","category":"operationnel","description":"Participation au vote qui s''effondre après deux semaines","probability":4,"impact":3,"critical":false,"warning_signs":["baisse de plus de 40 % entre deux votes"],"prevention":["relais par établissements scolaires et centres sociaux","feuilleton hebdomadaire","votes courts (30 s)"],"continuity_plan":"Fusion de deux modules et raccourcissement à 6 semaines","owner_role":"animateur de communauté","status":"ouvert"},{"id":"R3","category":"reputationnel","description":"Le sport obtenu est peu jouable ou ennuyeux et le tournoi déçoit","probability":3,"impact":3,"critical":false,"warning_signs":["tests jugés confus"],"prevention":["propositions préparées en atelier","deux tests sur le jeu complet en semaines 6 et 7"],"continuity_plan":"Tournoi présenté comme « version 1 » avec vote d''ajustement immédiat","owner_role":"EVENT LAB","status":"ouvert"},{"id":"R4","category":"financier","description":"Absence de commanditaire : le modèle n''a aucune recette autonome","probability":4,"impact":3,"critical":false,"warning_signs":["aucune ville intéressée après 10 rendez-vous"],"prevention":["pilote réduit à 4 semaines dans un établissement"],"continuity_plan":"Abandon ou format réduit pour établissements scolaires","owner_role":"EVENT LAB","status":"ouvert"},{"id":"R5","category":"juridique","description":"Votes manipulés (comptes multiples) ou données de mineurs mal gérées","probability":3,"impact":3,"critical":false,"warning_signs":["pics de votes anormaux"],"prevention":["compte vérifié, un vote par personne","minimisation des données"],"continuity_plan":"Annulation et nouveau vote","owner_role":"EVENT LAB","status":"ouvert"}],"compliance":[{"id":"C1","item":"Assurance responsabilité civile couvrant