  ('padel-royale', '0.1.0', 'PADEL ROYALE', '{"id":"padel-royale","version":"0.1.0","status":"draft","maturity":"concept","parent":null,"identity":{"name":"PADEL ROYALE","tagline":"Les pistes s''éteignent une à une. Le dernier debout gagne.","pitch":"Soirée de padel en inscription individuelle avec partenaires tournants et classement individuel (logique déjà connue des formats americano et mexicano), à laquelle s''ajoute une mécanique d''élimination empruntée au « battle royale » du jeu vidéo : à chaque palier, une ou deux pistes s''éteignent et les joueurs au plus faible total individuel passent sur une piste de repêchage. Les quatre derniers jouent la finale sur la piste centrale, chacun associé tour à tour aux trois autres. Produit vendu aux clubs sous forme de kit (règlement, outil de rotation, signalétique, gabarits de communication). Différenciation réelle mais modeste : le cœur du format (rotation et classement individuel) existe déjà.","disciplines":["padel"],"sectors":["sport amateur","clubs de raquette","jeu vidéo (logique transposée)"],"directions":["optimise"],"objectives":["Donner un enjeu et une narration à la soirée americano des clubs","Remplir des créneaux en heures creuses","Faire venir des joueurs sans partenaire","Créer une finale regardée par les joueurs éliminés"],"audiences":[{"segment":"Joueurs de padel loisirs et intermédiaires sans partenaire fixe","role":"participant","motivation":"Jouer avec des inconnus de son niveau, enjeu, soirée sociale","willingness_to_pay":"Hypothèse : 30–40 € par joueur pour 3 h, balles et boisson incluses (aucune donnée de prix sourcée)"},{"segment":"Gérants de clubs de padel","role":"organisateur","motivation":"Fidéliser, remplir les heures creuses, animer la communauté","willingness_to_pay":"Hypothèse : 100–200 € par soirée ou 49–99 € par mois de licence — à tester"},{"segment":"Marques d''équipement et commerces locaux","role":"sponsor","motivation":"Visibilité auprès d''une communauté ciblée","willingness_to_pay":"Hypothèse : dotation en nature ou 200–500 € par soirée"}],"inspirations":[{"source_event":"Format americano (padel)","source_sector":"padel","borrowed_logic":"Partenaires tournants, points individuels cumulés","adaptation":"Repris tel quel comme base : ce n''est pas une innovation du concept","source_ref":"S-PADEL-AMER"},{"source_event":"Format mexicano (padel)","source_sector":"padel","borrowed_logic":"Appariements recalculés à chaque tour selon le classement","adaptation":"Appariement par classement dans chaque palier","source_ref":"S-PADEL-MEX"},{"source_event":"King of the Court (padel)","source_sector":"padel","borrowed_logic":"Pistes hiérarchisées, piste du haut valorisée","adaptation":"La piste centrale devient la piste de finale ; les pistes ne montent ni ne descendent, elles ferment","source_ref":"S-PADEL-KOTC"},{"source_event":"Genre « battle royale » (jeu vidéo)","source_sector":"esport / jeu vidéo","borrowed_logic":"Zone de jeu qui se réduit par paliers, survivants","adaptation":"Fermeture physique des pistes (lumière coupée) à heure fixe ; aucun nom ni élément d''un jeu existant n''est repris"}]},"format":{"summary":"Soirée de 3 h pour 24 joueurs (6 pistes au départ). Palier 1 (6 pistes, 3 tours de 15 min) ; fermeture de 2 pistes ; palier 2 (4 pistes, 16 joueurs, 3 tours) ; fermeture de 2 pistes ; palier 3 (2 pistes, 8 joueurs, 2 tours) ; finale à 4 sur la piste centrale (3 manches, chaque joueur associé une fois à chacun des trois autres). Les éliminés rejoignent une piste de repêchage en americano libre : le meilleur du repêchage récupère une place au palier suivant.","rules_summary":"Points individuels = jeux gagnés par la paire à laquelle on appartient sur le tour. Appariement mexicano dans chaque palier (1 et 4 contre 2 et 3 sur chaque piste). À chaque fermeture, les joueurs au plus faible total cumulé quittent la compétition principale. Égalité : différence de jeux puis tirage au sort. Finale : 3 manches de 6 jeux, classement individuel.","duration_hours":3,"edition_cadence":"mensuelle par club ; circuit inter-clubs possible","building_blocks":[{"type":"regles","label":"Rotation des partenaires et classement individuel (base americano/mexicano)","parameters":{"joueurs":24,"tour_min":15}},{"type":"mecanique_jeu","label":"Fermeture des pistes par paliers","parameters":{"paliers":[6,4,2,1],"eliminés_par_palier":[8,8,4]}},{"type":"qualification","label":"Piste de repêchage","parameters":{"places_rendues_par_palier":1}},{"type":"mise_en_scene","label":"Extinction de la piste et annonce des éliminés","parameters":{"cue":"coupure lumière de la piste + son"}},{"type":"experience_digitale","label":"Classement individuel en direct sur écran (outil de rotation)","parameters":{}},{"type":"monetisation","label":"Frais d''inscription individuels, bar du club, licence du kit","parameters":{}},{"type":"creation_contenu","label":"Vidéo verticale de l''extinction des pistes et de la finale","parameters":{}}]},"participants":{"unit":"individu","count":{"prudent":16,"central":24,"ambitieux":32},"categories":["niveau loisirs","niveau intermédiaire","mixte possible"]},"audience":{"attendance":{"prudent":10,"central":25,"ambitieux":40},"paying_share":0,"avg_dwell_min":90},"venue_requirements":{"setting":"interieur","min_area_m2":1200,"spaces":[{"id":"pistes","type":"aire_de_jeu","label":"4 à 6 pistes de padel de 20 × 10 m","area_m2":1200},{"id":"centrale","type":"aire_de_jeu","label":"Piste centrale visible depuis le bar"},{"id":"bar","type":"restauration","label":"Bar ou club-house"}],"power_kw":2,"internet":"Wi-Fi du club pour l''outil de rotation","notes":"Club existant avec au moins 4 pistes. La commande lumière par piste est un plus pour la mise en scène ; sinon signalétique « piste fermée »."},"competition":{"stages":[{"id":"palier-1","label":"Palier 1 (6 pistes)","type":"battle_royale","entrants":24,"slot_duration_min":15,"changeover_min":2,"parallel_units":6,"advance":16},{"id":"palier-2","label":"Palier 2 (4 pistes)","type":"battle_royale","entrants":16,"slot_duration_min":15,"changeover_min":2,"parallel_units":4,"advance":8},{"id":"palier-3","label":"Palier 3 (2 pistes)","type":"battle_royale","entrants":8,"slot_duration_min":15,"changeover_min":2,"parallel_units":2,"advance":4},{"id":"finale","label":"Finale à 4","type":"round_robin","entrants":4,"groups":1,"slot_duration_min":15,"changeover_min":2,"parallel_units":1}]},"budget":{"currency":"EUR","contingency_rate":0.1,"expenses":[{"id":"e-pistes","category":"lieu","label":"Coût d''opportunité des pistes en heures creuses (≈ 4 pistes-équivalent × 3 h × 15 €)","amount":180,"basis":"fixed","certainty":"hypothese","priority":1},{"id":"e-balles","category":"materiel","label":"Balles","amount":100,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-animateur","category":"personnel","label":"Animateur / juge-arbitre (5 h)","amount":150,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-licence","category":"prestation","label":"Licence du kit PADEL ROYALE par soirée","amount":150,"basis":"fixed","certainty":"hypothese","priority":2},{"id":"e-dotations","category":"recompenses","label":"Dotations finale","amount":200,"basis":"fixed","certainty":"estimation","priority":3,"optional":true},{"id":"e-boisson","category":"restauration","label":"Boisson offerte par joueur","amount":3,"basis":"per_participant","certainty":"estimation","priority":2}],"revenues":[{"id":"r-inscriptions","stream":"inscriptions","label":"Inscription individuelle 35 €","unit_amount":35,"basis":"per_participant","certainty":"probable","cash_offset_days":-3},{"id":"r-bar","stream":"restauration","label":"Bar : 5 € par spectateur, marge 60 % (hypothèses)","unit_amount":5,"basis":"per_attendee","margin_rate":0.6,"certainty":"probable"},{"id":"r-sponsor","stream":"sponsoring","label":"Partenaire de la piste centrale","unit_amount":300,"basis":"fixed","certainty":"hypothetical"}]},"risks":[{"id":"R1","category":"securite","description":"Blessures liées à l''enchaînement de tours sans repos (claquages, chocs contre les vitres)","probability":2,"impact":3,"critical":false,"warning_signs":["joueurs de niveau hétérogène sur une même piste"],"prevention":["échauffement collectif","2 min de pause entre tours","inscription par niveau"],"continuity_plan":"Remplacement par le meilleur du repêchage ; trousse de secours et procédure d''appel des secours affichée","owner_role":"animateur","status":"ouvert"},{"id":"R2","category":"reputationnel","description":"Frustration des joueurs éliminés tôt qui ont payé autant que les finalistes","probability":4,"impact":3,"critical":true,"warning_signs":["départs après le palier 1","avis négatifs"],"prevention":["piste de repêchage garantissant un temps de jeu minimal de 2 h","élimination annoncée dans le règlement"],"continuity_plan":"Si le temps de jeu des éliminés passe sous 2 h, convertir la piste de repêchage en americano libre jusqu''à la fin","owner_role":"gérant du club","status":"ouvert"},{"id":"R3","category":"financier","description":"Format copiable sans coût par n''importe quel club : la licence ne trouve pas preneur","probability":4,"impact":3,"critical":false,"warning_signs":["clubs testant le format puis le reproduisant sans licence"],"prevention":["valeur placée dans l''outil et le classement inter-clubs plutôt que dans la règle"],"continuity_plan":"Repositionner le produit en événement de contenu gratuit pour un partenaire ou abandonner la licence","owner_role":"EVENT LAB","status":"ouvert"},{"id":"R4","category":"operationnel","description":"Désistements de dernière minute qui cassent le nombre multiple de 4","probability":3,"impact":2,"critical":false,"warning_signs":["moins de 24 confirmations à J-1"],"prevention":["liste d''attente","paiement à l''inscription"],"continuity_plan":"Joueur du club en remplaçant ; palier 1 à 5 pistes","owner_role":"animateur","status":"ouvert"}],"compliance":[{"id":"C1","item":"Assurance responsabilité civile de l''organisateur (club) couvrant les non-membres","authority":"Assureur du club","mandatory":true,"status":"a_verifier"},{"id":"C2","item":"Si la soirée est présentée comme tournoi homologué ou ouverte aux licenciés avec prix : règles fédérales applicables (autorisation de la fédération délégataire au-delà d''un seuil de prix — Code du sport, art. L331-5, à vérifier)","authority":"Fédération délégataire du padel","mandatory":true,"status":"a_verifier"},{"id":"C3","item":"Données des joueurs et classement public : information RGPD, droit d''opposition à l''affichage du nom","authority":"Club (responsable de traitement)","mandatory":true,"status":"a_verifier"},{"id":"C4","item":"Usage du terme « royale » / « battle royale » : vérifier l''absence de droits antérieurs (INPI, EUIPO)","authority":"Conseil en propriété industrielle","mandatory":true,"status":"a_verifier"}],"kpis":[{"id":"K1","label":"Taux de remplissage de la soirée","phase":"avant","target":100,"unit":"% (24 joueurs)","measure":"inscriptions payées à J-2"},{"id":"K2","label":"Temps de jeu minimal d''un joueur éliminé au palier 1","phase":"pendant","target":120,"unit":"min","measure":"relevé de l''outil de rotation"},{"id":"K3","label":"Taux de réinscription à la soirée suivante","phase":"apres","target":50,"unit":"%","measure":"inscrits revenus / inscrits"},{"id":"K4","label":"Clubs ayant payé une licence après une soirée test","phase":"apres","target":3,"unit":"clubs","measure":"contrats signés sur 10 clubs testés"}],"media":{"viral_moments":["Extinction d''une piste en pleine soirée","Annonce des éliminés sur écran","Retour d''un joueur par le repêchage","Dernier point de la finale à 4"],"photo_spots":["Piste centrale éclairée, autres pistes éteintes"],"channels":["Instagram","TikTok","groupes de messagerie du club"]},"gamification":[{"mechanic":"Classement individuel cumulé et repêchage","target_role":"participant","description":"Chaque jeu compte pour le total individuel ; une place rendue par palier au meilleur du repêchage","fairness_note":"Inscription par niveau pour éviter des écarts trop forts ; règles d''égalité publiées avant la soirée"}],"evaluation":{"type":"previsionnelle","date":"2026-11-24","ratings":{"originalite":{"rating":2.5,"justification":"Entre ancres 1 et 3. Le cœur du format (rotation des partenaires, classement individuel, appariement par classement) existe à l''identique dans l''americano et le mexicano ; la piste centrale et la hiérarchie des pistes existent dans le King of the Court. La seule brique nouvelle trouvée est la fermeture des pistes par paliers avec repêchage ; aucune source ne décrit ce format sous forme identique.","evidence":"benchmark_source","improvements":["Ajouter un classement individuel inter-clubs persistant (circuit) qui crée une valeur que le club ne peut pas reproduire seul"]},"experience_utilisateur":{"rating":3,"justification":"Ancre 3. Règles compréhensibles en moins de 2 minutes, rythme soutenu (tours de 15 min). L''élimination crée une expérience inégale entre finalistes et éliminés ; le repêchage limite le problème sans le supprimer.","evidence":"jugement_expert","improvements":["Garantir 2 h de jeu à chaque joueur quelle que soit son élimination"]},"faisabilite_technique":{"rating":4.5,"justification":"Proche de l''ancre 5. Pistes existantes, outils de rotation déjà disponibles sur le marché, aucune compétence rare ; plan B tableur.","evidence":"jugement_expert","improvements":[]},"viabilite_economique":{"rating":2.5,"justification":"Entre ancres 1 et 3. Au scénario central, les inscriptions couvrent à peine les coûts si les pistes sont valorisées en heures creuses ; au prudent (16 joueurs), la perte dépasse 40 % des dépenses. L''intérêt économique pour le club est la fidélisation, non la marge de la soirée. Règle de cohérence du portefeuille : note de base lue sur le résultat §7.1 (ancres), puis décote de 1,5 lorsque la recette principale dépend d''un prix ou d''un acheteur non testé, et de 0,5 supplémentaire en cas de risque d''investissement ou d''utilisation.","evidence":"jugement_expert","improvements":["Seuil de déclenchement à 20 inscrits payés à J-3"]},"potentiel_mediatique":{"rating":3,"justification":"Ancre 3. Deux à trois moments filmables (extinction des pistes, annonce des éliminés, finale). Audience limitée à la communauté du club.","evidence":"jugement_expert","improvements":["Gabarit vidéo verticale fourni dans le kit"]},"reproductibilite":{"rating":4.5,"justification":"Proche de l''ancre 5. Un club peut reproduire le format avec un règlement d''une page et un outil de rotation ; cette facilité est aussi la faiblesse commerciale du concept.","evidence":"benchmark_source","improvements":[]},"adaptabilite_lieux":{"rating":2,"justification":"Entre ancres 1 et 3. Un seul type de lieu réaliste : club disposant d''au moins 4 pistes. Les pistes temporaires existent pour de grands événements mais sont hors budget à cette échelle.","evidence":"jugement_expert","improvements":["Variante 3 pistes pour 16 joueurs"]},"accessibilite_inclusion":{"rating":2.5,"justification":"Entre ancres 1 et 3. Inscription par niveau et mixité possibles ; prix élevé pour un public jeune ; aucun aménagement handi conçu.","evidence":"jugement_expert","improvements":["Soirées par niveau et tarif réduit étudiants"]},"potentiel_commercial":{"rating":2.5,"justification":"Entre ancres 1 et 3. Trois sources (inscriptions, bar, partenaire de piste) ; la licence est peu crédible car la règle n''est pas protégeable et se copie sans coût.","evidence":"jugement_expert","improvements":["Monétiser l''outil et le circuit plutôt que la règle"]},"responsabilite_environnementale":{"rating":3,"justification":"Ancre 3. Infrastructures existantes, faible matériel ; déplacements en voiture probables, balles non recyclées.","evidence":"jugement_expert","improvements":["Collecte et recyclage des balles"]}},"gates":{"securite":{"status":"ok","notes":"Aucun risque sécurité/santé d''impact 5 et de probabilité ≥ 3 sans prévention. Risques sécurité/santé d''impact ≥ 4 suivis : aucun. Le dimensionnement des secours et de la jauge relève d''acteurs externes agréés. || calcul : Aucun risque sécurité/santé d''impact 5 et de probabilité ≥ 3 sans prévention. Risques sécurité/santé d''impact ≥ 4 suivis : aucun. Le dimensionnement des secours et de la jauge relève d''acteurs externes agréés."},"conformite_reglementaire":{"status":"a_verifier","notes":"4 point(s) obligatoire(s) à vérifier (C1, C2, C3, C4) ; règle §1.5 appliquée au stade blueprint, le portefeuille servant de porte d''entrée au blueprint. || calcul : 4 point(s) obligatoire(s) à vérifier (C1, C2, C3, C4) ; règle §1.5 appliquée au stade blueprint, le portefeuille servant de porte d''entrée au blueprint."},"risques_critiques":{"status":"ok","notes":"Risques critiques identifiés (R2), tous dotés d''un plan de continuité. || calcul : Risques critiques identifiés (R2), tous dotés d''un plan de continuité."}},"computed":{"score":62,"grade":"C","confidence":0.37,"verdict":"sous_reserve","gains":{"originalite":6,"experience_utilisateur":6,"faisabilite_technique":1.5,"viabilite_economique":7.5,"potentiel_mediatique":4,"reproductibilite":1,"adaptabilite_lieux":4.8,"accessibilite_inclusion":2.5,"potentiel_commercial":2.5,"responsabilite_environnementale":2},"score_if_plus_one":80}},"hypotheses":["Prix d''inscription 35 € par joueur : hypothèse non sourcée.","Coût d''opportunité des pistes en heures creuses : 15 € par piste et par heure, hypothèse.","Les clubs paient une licence pour un format qu''ils pourraient copier : hypothèse jugée fragile."],"sources":[{"id":"S-PADEL-AMER","title":"Americano (padel) — article explicatif","publisher":"padel.fyi","url":"https://www.padel.fyi/articles/americano/","accessed_at":"2026-11-24","reliability":"C","verification":"via résultats de recherche"},{"id":"S-PADEL-MEX","title":"Mexicano format","publisher":"Skedge (éditeur de logiciel)","url":"https://skedge-web.web.app/resources/mexicano-format","accessed_at":"2026-11-24","reliability":"C","verification":"via résultats de recherche"},{"id":"S-PADEL-KOTC","title":"Padel tournament formats: americano, king of the court","publisher":"Padelbrowser","url":"https://www.padelbrowser.com/blog/padel-tournament-formats-americano-king-of-the-court","accessed_at":"2026-11-24","reliability":"C","verification":"via résultats de recherche"},{"id":"S-FLT-PROG","title":"Règlement officiel — tournoi progressif (padel)","publisher":"Fédération luxembourgeoise de tennis","url":"https://padel.flt.lu/media/69bd203fc1038_reglement-officiel-tournoi-progressif.pdf","accessed_at":"2026-11-24","reliability":"A","verification":"via résultats de recherche"},{"id":"S-ONEPOINT","title":"One Point Challenge Tour: a padel tournament and festival with a high-octane format on the Île de Puteaux","publisher":"Sortiraparis","url":"https://www.sortiraparis.com/en/what-to-do-in-paris/sport-wellness/articles/349160-one-point-challenge-tour-a-padel-tournament-and-festival-in-a-knockout-format-on-ile-de-puteaux","accessed_at":"2026-11-24","reliability":"B","verification":"via résultats de recherche"},{"id":"S-WECOURTS","title":"Changelog — live results (support du format King of the Court avec affichage TV)","publisher":"WeCourts","url":"https://wecourts.featurebase.app/en/changelog/live-results","accessed_at":"2026-11-24","reliability":"D","verification":"via résultats de recherche"}],"history":[{"version":"0.1.0","date":"2026-11-24","author":"EVENT LAB — portefeuille v0.2","summary":"Concept conservé et différencié après vérification : americano, mexicano et King of the Court existent ; la fermeture des pistes par paliers avec repêchage n''a pas été trouvée sous forme identique.","decisions":["Base americano/mexicano assumée comme existante","Ajout du repêchage pour limiter la frustration des éliminés"],"approved_by":null}]}'::jsonb),
  ('repar-arene', '0.1.0', 'RÉPAR''ARÈNE', '{"id":"repar-arene","version":"0.1.0","status":"draft","maturity":"concept","parent":null,"identity":{"name":"RÉPAR''ARÈNE","tagline":"Votre objet est en panne. Six duos ont 30 minutes.","pitch":"Remplace la graine draft-night (recoupement avec l''existant interne du porteur et avec des ligues à draft existantes). Spectacle public de réparation en compétition : les habitants apportent des objets en panne déclarés à l''avance (petit électroménager, vélo, vêtement, lampe, jouet) ; six duos — un bénévole amateur et un artisan ou réparateur local — s''affrontent en trois manches chronométrées (diagnostic éclair, réparation, objet mystère) devant un jury et un public qui pronostique la panne. Le propriétaire repart avec son objet réparé, à prix coûtant des pièces plafonné. Chaque réparation est documentée en fiche publique (bibliothèque de tutoriels), filmée en gros plan et pesée : le kilo d''objets sauvés est l''indicateur central. Acheteurs visés : intercommunalités et syndicats chargés de la prévention des déchets, bailleurs sociaux, médiathèques et tiers-lieux. Originalité non vérifiée par recherche web (budget épuisé) : à contrôler en priorité.","disciplines":[],"sectors":["économie circulaire et réparation","jeux télévisés de compétition (logique transposée)","artisanat","action publique de prévention des déchets"],"directions":["communautaire","hybride"],"objectives":["Rendre la réparation visible, désirable et apprise","Mesurer un impact environnemental concret (masse d''objets sauvés)","Mettre en avant les artisans réparateurs du territoire","Offrir aux collectivités une action de prévention des déchets à forte audience"],"audiences":[{"segment":"Intercommunalités et syndicats de collecte et traitement des déchets","role":"organisateur","motivation":"Actions de prévention visibles et mesurables","willingness_to_pay":"Hypothèse : 7 000 € par épisode dans un contrat de série de 4 — non testée"},{"segment":"Habitants porteurs d''objets en panne","role":"participant","motivation":"Récupérer un objet réparé, comprendre la panne","willingness_to_pay":"Pièces à prix coûtant, plafonnées à 15 € (hypothèse)"},{"segment":"Artisans réparateurs, bénévoles d''ateliers de réparation","role":"participant","motivation":"Visibilité, nouveaux clients, reconnaissance","willingness_to_pay":"Indemnité versée (150 € par duo) — hypothèse"},{"segment":"Familles et curieux","role":"spectateur","motivation":"Spectacle gratuit, suspense, apprentissage","willingness_to_pay":"0 € (gratuit)"},{"segment":"Enseignes de bricolage, chambres consulaires des métiers","role":"sponsor","motivation":"Image, promotion des métiers de la réparation","willingness_to_pay":"Hypothèse : 1 000 € par épisode"}],"inspirations":[{"source_event":"Ateliers de réparation bénévoles et participatifs","source_sector":"économie circulaire","borrowed_logic":"Réparer ensemble des objets apportés par les habitants","adaptation":"Passage d''un atelier sans enjeu à un spectacle compétitif en manches ; la marque d''un réseau existant d''ateliers n''est pas utilisée (vérifier les droits antérieurs)"},{"source_event":"Concours culinaires télévisés à manches et jury","source_sector":"télévision","borrowed_logic":"Manches chronométrées, épreuve mystère, jury, élimination","adaptation":"Transposées à la réparation ; aucun titre ni identité d''émission repris"},{"source_event":"LA JOUTE (portefeuille EVENT LAB)","source_sector":"éloquence","borrowed_logic":"Explication publique notée","adaptation":"Le duo est aussi noté sur la qualité de l''explication donnée au propriétaire"}]},"format":{"summary":"Samedi après-midi, 2 h 30, dans une halle, une médiathèque ou un tiers-lieu. Inscriptions préalables des objets avec photo et description de la panne (tri par l''équipe). Manche 1 — diagnostic éclair : 5 min par objet, le public pronostique la panne par QR. Manche 2 — réparation : 30 min, chaque duo reçoit deux objets. Manche 3 — objet mystère pour les deux meilleurs duos. Écran géant avec caméra en gros plan, commentaire en direct. Remise au propriétaire, pesée, fiche de réparation publiée.","rules_summary":"Points : réparation réussie (50), coût des pièces (jusqu''à 20, moins c''est cher plus c''est haut), explication au propriétaire notée par lui (jusqu''à 20), temps (jusqu''à 10). Objets exclus : appareils à gaz, chauffage, systèmes de sécurité, batteries gonflées, objets sous garantie. Tout appareil électrique réparé passe un contrôle de sécurité avant restitution ; en cas de doute, il n''est pas rendu fonctionnel et le propriétaire est orienté vers un professionnel.","duration_hours":2.5,"edition_cadence":"série de 4 à 6 épisodes par an dans différents quartiers, finale annuelle","building_blocks":[{"type":"regles","label":"Trois manches chronométrées, barème réparation/coût/explication/temps","parameters":{"duos":6,"objets_par_duo":2}},{"type":"interaction_public","label":"Pronostic gratuit de la panne par QR","parameters":{}},{"type":"mise_en_scene","label":"Caméra gros plan sur écran géant, commentaire, pesée publique","parameters":{}},{"type":"experience_digitale","label":"Bibliothèque publique des fiches de réparation","parameters":{}},{"type":"creation_contenu","label":"Avant/après, accélérés, tutoriels courts","parameters":{}},{"type":"fidelisation","label":"Classement annuel des duos, finale","parameters":{}},{"type":"activation_partenaire","label":"Enseigne de bricolage ou chambre des métiers partenaire de saison","parameters":{}},{"type":"monetisation","label":"Contrat de série avec une collectivité, sponsor","parameters":{}}]},"participants":{"unit":"equipe","count":{"prudent":6,"central":6,"ambitieux":6},"team_size":2,"categories":["duos amateur + professionnel"]},"audience":{"attendance":{"prudent":60,"central":120,"ambitieux":200},"paying_share":0,"avg_dwell_min":120},"venue_requirements":{"setting":"interieur","min_area_m2":250,"spaces":[{"id":"etablis","type":"aire_de_jeu","label":"Six établis éclairés, ventilés, avec alimentation protégée"},{"id":"public","type":"tribune","label":"Public assis ou debout 60–200 personnes"},{"id":"depot","type":"accueil","label":"Dépôt et restitution des objets, pesée"},{"id":"regie","type":"regie","label":"Caméra gros plan, écran, son"}],"power_kw":9,"internet":"nécessaire pour le pronostic et la publication des fiches","notes":"Circuits électriques protégés par différentiel ; distance de sécurité entre établis et public."},"budget":{"currency":"EUR","contingency_rate":0.1,"expenses":[{"id":"e-lieu","category":"lieu","label":"Salle (souvent municipale)","amount":300,"basis":"fixed","certainty":"hypothese","priority":1},{"id":"e-animation","category":"animation","label":"Animateur-commentateur","amount":500,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-duos","category":"personnel","label":"Indemnités des six duos (6 × 150 €)","amount":900,"basis":"fixed","certainty":"hypothese","priority":1},{"id":"e-pieces","category":"consommables","label":"Pièces et consommables (au-delà de la participation plafonnée des propriétaires)","amount":400,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-outillage","category":"materiel","label":"Outillage, testeur de sécurité électrique, protections","amount":300,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-av","category":"technique","label":"Écran, caméra gros plan, son","amount":600,"basis":"fixed","certainty":"estimation","priority":2},{"id":"e-video","category":"media","label":"Montage des tutoriels et avant/après","amount":800,"basis":"fixed","certainty":"estimation","priority":2},{"id":"e-assurance","category":"assurance","label":"Assurance RC incluant l''activité de réparation","amount":250,"basis":"fixed","certainty":"hypothese","priority":1},{"id":"e-com","category":"communication","label":"Communication et appel aux objets","amount":500,"basis":"fixed","certainty":"estimation","priority":2},{"id":"e-jury","category":"competition","label":"Défraiement du jury","amount":150,"basis":"fixed","certainty":"estimation","priority":3},{"id":"e-coordination","category":"prestation","label":"Format et coordination EVENT LAB","amount":1200,"basis":"fixed","certainty":"hypothese","priority":1}],"revenues":[{"id":"r-contrat","stream":"autre","label":"Épisode d''un contrat de série signé avec une collectivité (engagement des dépenses après signature)","unit_amount":7000,"basis":"fixed","certainty":"secured"},{"id":"r-sponsor","stream":"sponsoring","label":"Partenaire de saison (quote-part par épisode)","unit_amount":1000,"basis":"fixed","certainty":"hypothetical"}]},"risks":[{"id":"R1","category":"securite","description":"Électrisation, brûlure ou coupure pendant une réparation, projection vers le public","probability":2,"impact":4,"critical":false,"warning_signs":["appareil non débranché","batterie déformée"],"prevention":["appareils électriques confiés au membre qualifié du duo","réparations hors tension, testeur de sécurité","équipements de protection","zone public à distance"],"continuity_plan":"Arrêt de la manche, prise en charge par le secouriste, retrait de l''objet","owner_role":"référent sécurité","status":"ouvert"},{"id":"R2","category":"juridique","description":"Responsabilité en cas de dommage causé ultérieurement par un objet réparé (incendie, choc électrique)","probability":2,"impact":5,"critical":true,"warning_signs":["objets à risque inscrits"],"prevention":["liste d''objets exclus","contrôle de sécurité avant restitution","information écrite du propriétaire","avis d''assureur et de juriste avant le premier épisode"],"continuity_plan":"En cas de doute, objet restitué non remis en service avec orientation vers un professionnel ; déclaration à l''assureur","owner_role":"EVENT LAB","status":"ouvert"},{"id":"R3","category":"operationnel","description":"Objets apportés trop simples, trop complexes ou en nombre insuffisant","probability":3,"impact":3,"critical":false,"warning_signs":["moins de 20 objets inscrits à J-7"],"prevention":["inscription avec photo, tri préalable","réserve d''objets issus d''une ressourcerie"],"continuity_plan":"Objets de réserve fournis par une ressourcerie partenaire","owner_role":"coordinateur","status":"ouvert"},{"id":"R4","category":"reputationnel","description":"Réparations ratées en public, propriétaires déçus ; concurrence perçue par des réparateurs professionnels","probability":3,"impact":2,"critical":false,"warning_signs":["taux de réussite < 50 %"],"prevention":["un échec donne un diagnostic écrit et une orientation vers un artisan local","artisans associés à chaque duo"],"continuity_plan":"Bon de diagnostic remis au propriétaire","owner_role":"animateur","status":"ouvert"},{"id":"R5","category":"financier","description":"Aucune collectivité ne signe de contrat de série","probability":3,"impact":3,"critical":false,"warning_signs":["aucun rendez-vous obtenu en 2 mois"],"prevention":["épisode pilote cofinancé"],"continuity_plan":"Version associative allégée (sans vidéo ni indemnités), ou abandon","owner_role":"EVENT LAB","status":"ouvert"}],"compliance":[{"id":"C1","item":"Assurance responsabilité civile couvrant l''activité de réparation et les dommages ultérieurs ; régime de responsabilité applicable à une réparation bénévole ou rémunérée","authority":"Assureur, juriste","mandatory":true,"status":"a_verifier"},{"id":"C2","item":"Sécurité électrique des installations temporaires et des appareils restitués","authority":"Électricien qualifié, exploitant du lieu","mandatory":true,"status":"a_verifier"},{"id":"C3","item":"Effectif autorisé et classement ERP du lieu","authority":"Exploitant, mairie","mandatory":true,"status":"a_verifier"},{"id":"C4","item":"Pronostic gratuit avec lot : règlement et gratuité","authority":"Juriste","mandatory":true,"status":"a_verifier"},{"id":"C5","item":"Données des propriétaires et droit à l''image (diffusion des tutoriels)","authority":"Organisateur","mandatory":true,"status":"a_verifier"},{"id":"C6","item":"Noms et marques de réseaux d''ateliers de réparation existants : ne pas les utiliser sans accord","authority":"Conseil en propriété industrielle","mandatory":true,"status":"a_verifier"}],"kpis":[{"id":"K1","label":"Objets inscrits à J-7","phase":"avant","target":24,"unit":"objets","measure":"formulaire d''inscription"},{"id":"K2","label":"Taux de réparation réussie","phase":"pendant","target":60,"unit":"%","measure":"fiches de réparation"},{"id":"K3","label":"Masse d''objets remis en service","phase":"pendant","target":40,"unit":"kg par épisode (hypothèse)","measure":"pesée publique"},{"id":"K4","label":"Spectateurs","phase":"pendant","target":120,"unit":"personnes","measure":"comptage"},{"id":"K5","label":"Renouvellement du contrat de série","phase":"apres","target":1,"unit":"contrat","measure":"délibération ou bon de commande"}],"media":{"viral_moments":["Avant/après en accéléré","Diagnostic du public contre diagnostic de l''expert","Objet mystère de la finale","Pesée cumulée de la saison"],"photo_spots":["Mur des objets sauvés","Balance géante"],"channels":["Instagram","TikTok","YouTube (tutoriels)","presse locale","sites des collectivités"]},"gamification":[{"mechanic":"Pronostic de la panne","target_role":"spectateur","description":"Le public choisit parmi trois diagnostics","fairness_note":"Gratuit, lot symbolique"},{"mechanic":"Compteur collectif de kilos sauvés","target_role":"spectateur","description":"Objectif annuel partagé par le territoire","fairness_note":"Mesure réelle, pas d''incitation à apporter des objets non nécessaires"}],"evaluation":{"type":"previsionnelle","date":"2026-11-24","ratings":{"originalite":{"rating":3,"justification":"Ancre 3 (combinaison nouvelle de briques connues). Les ateliers de réparation participatifs et les concours à manches télévisés existent ; leur combinaison en spectacle compétitif n''a pas pu être recherchée sur le web (budget de recherche épuisé). Note provisoire, confiance minimale.","evidence":"jugement_expert","improvements":["Recherche d''antériorité prioritaire (compétitions de réparation, émissions de réparation)"]},"experience_utilisateur":{"rating":3,"justification":"Ancre 3. Enjeu réel pour les propriétaires, apprentissage pour le public ; une réparation est lente à regarder : les temps faibles dépendent de la caméra gros plan et du commentaire.","evidence":"jugement_expert","improvements":["Rotation de l''écran entre établis, commentaire à deux voix"]},"faisabilite_technique":{"rating":3,"justification":"Ancre 3. Outillage courant ; points à sécuriser : sécurité électrique, tri des objets, responsabilité sur les objets restitués.","evidence":"jugement_expert","improvements":[]},"viabilite_economique":{"rating":3,"justification":"Ancre 3. Le calcul §7.1 donne +7 % au central et −6 % au prudent si le contrat de série est signé avant engagement des dépenses (base 4,5) ; décote de 1,5 car prix et acheteur public ne sont pas testés. Règle de cohérence du portefeuille : note de base lue sur le résultat §7.1 (ancres), puis décote de 1,5 lorsque la recette principale dépend d''un prix ou d''un acheteur non testé, et de 0,5 supplémentaire en cas de risque d''investissement ou d''utilisation.","evidence":"jugement_expert","improvements":["Rendez-vous avec trois collectivités compétentes en prévention des déchets"]},"potentiel_mediatique":{"rating":3.5,"justification":"Entre ancres 3 et 5. Avant/après et tutoriels conçus pour le format vertical, contenu réutilisable par les collectivités ; audience surtout locale.","evidence":"jugement_expert","improvements":[]},"reproductibilite":{"rating":3.5,"justification":"Entre ancres 3 et 5. Kit et barème standardisables ; dépend du recrutement d''artisans locaux à chaque épisode.","evidence":"jugement_expert","improvements":["Convention type avec la chambre des métiers"]},"adaptabilite_lieux":{"rating":4,"justification":"Entre ancres 3 et 5. Halle, médiathèque, tiers-lieu, salle polyvalente, marché couvert ; extérieur sous tente possible.","evidence":"jugement_expert","improvements":[]},"accessibilite_inclusion":{"rating":3.5,"justification":"Entre ancres 3 et 5. Gratuit, intergénérationnel, sans prérequis pour le public ; duos ouverts aux amateurs ; aménagements handicap à prévoir au cas par cas.","evidence":"jugement_expert","improvements":[]},"potentiel_commercial":{"rating":3.5,"justification":"Entre ancres 3 et 5. Contrats de série publics, partenaires, contenus, licence possible aux réseaux de réparation ; dépend fortement de la commande publique.","evidence":"jugement_expert","improvements":[]},"responsabilite_environnementale":{"rating":5,"justification":"Ancre 5. La raison d''être du format est la remise en service d''objets, avec mesure systématique (pesée) ; matériel réemployé, public local.","evidence":"jugement_expert","improvements":[]}},"gates":{"securite":{"status":"ok","notes":"Aucun risque sécurité/santé d''impact 5 et de probabilité ≥ 3 sans prévention. Risques sécurité/santé d''impact ≥ 4 suivis : R1. Le dimensionnement des secours et de la jauge relève d''acteurs externes agréés. || calcul : Aucun risque sécurité/santé d''impact 5 et de probabilité ≥ 3 sans prévention. Risques sécurité/santé d''impact ≥ 4 suivis : R1. Le dimensionnement des secours et de la jauge relève d''acteurs externes agréés."},"conformite_reglementaire":{"status":"a_verifier","notes":"6 point(s) obligatoire(s) à vérifier (C1, C2, C3, C4, C5, C6) ; règle §1.5 appliquée au stade blueprint, le portefeuille servant de porte d''entrée au blueprint. || calcul : 6 point(s) obligatoire(s) à vérifier (C1, C2, C3, C4, C5, C6) ; règle §1.5 appliquée au stade blueprint, le portefeuille servant de porte d''entrée au blueprint."},"risques_critiques":{"status":"ok","notes":"Risques critiques identifiés (R2), tous dotés d''un plan de continuité. || calcul : Risques critiques identifiés (R2), tous dotés d''un plan de continuité."}},"computed":{"score":67,"grade":"B","confidence":0.3,"verdict":"sous_reserve","gains":{"originalite":4.8,"experience_utilisateur":6,"faisabilite_technique":6,"viabilite_economique":6,"potentiel_mediatique":3,"reproductibilite":3,"adaptabilite_lieux":1.6,"accessibilite_inclusion":1.5,"potentiel_commercial":1.5,"responsabilite_environnementale":0},"score_if_plus_one":86}},"hypotheses":["Prix de 7 000 € par épisode dans un contrat de 4 épisodes : hypothèse non testée.","Les collectivités compétentes en prévention des déchets disposent de budgets d''animation mobilisables : hypothèse.","Masse moyenne remise en service par épisode : 40 kg, hypothèse sans donnée.","Aucune vérification web d''originalité ni d''homonymie n''a pu être faite (budget de recherche épuisé)."],"sources":[],"history":[{"version":"0.1.0","date":"2026-11-24","author":"EVENT LAB — portefeuille v0.2","summary":"Création en remplacement de draft-night, retiré pour recoupement avec l''existant interne du porteur (QUADRA, VITRINE) et l''existant externe (ligues amateurs à draft).","decisions":["Concept hors sport choisi conformément à la vocation multisectorielle d''EVENT LAB","Originalité et nom non vérifiés sur le web : à faire avant toute suite"],"approved_by":null}]}'::jsonb),
  ('silent-arena', '0.1.0', 'SILENT ARENA', '{"id":"silent-arena","version":"0.1.0","status":"draft","maturity":"concept","parent":null,"identity":{"name":"SILENT ARENA","tagline":"La ville dort. Le match, lui, se joue dans vos oreilles.","pitch":"Tournoi nocturne de foot à 5 ou de futsal de rue (toute discipline de nuit possible) sur un city-stade, une cour ou un toit situé en zone sensible au bruit. Aucune enceinte : le public porte des casques sans fil à trois canaux — commentaire en direct, DJ, micro de l''arbitre et du coach pendant les temps morts — et un quatrième canal d''audiodescription pour les spectateurs déficients visuels. L''arbitrage et le chronométrage passent par des signaux lumineux (pas de sifflet ni de buzzer sonore). La contrainte de lieu devient l''expérience. Briques existantes : casques « silent disco » dans des événements sportifs, retransmission du micro de l''arbitre aux spectateurs au rugby ; la combinaison en compétition conçue pour le silence n''a pas été trouvée. Recoupement interne signalé : le porteur dispose déjà, en basket, de « La Veillée — tournoi nocturne de gymnase » et de « Les Nocturnes — 3x3 au score cible » ; SILENT ARENA est donc positionné hors basket et comme une couche « silence » applicable à tout tournoi de nuit, y compris ces formats.","disciplines":["football à 5 / futsal de rue","toute compétition nocturne (module)"],"sectors":["sport amateur urbain","festivals (silent disco)","rugby (audio arbitre)","audiodescription"],"directions":["experimental","hybride"],"objectives":["Rendre possible un événement sportif nocturne là où le bruit l''interdit","Offrir une expérience d''écoute choisie (commentaire, musique, arbitre)","Proposer aux villes une animation de soirée estivale pour les jeunes, compatible avec le voisinage","Intégrer l''audiodescription dès la conception"],"audiences":[{"segment":"Jeunes 14–30 ans des quartiers denses","role":"spectateur","motivation":"Sortie nocturne gratuite ou peu chère, ambiance","willingness_to_pay":"Hypothèse : 0–3 € + caution casque ; signal : une soirée de retransmission sportive en casques a facturé 10 $ la location (Bangkok, 2023)"},{"segment":"Équipes amateurs 3x3","role":"participant","motivation":"Jouer de nuit, être commenté","willingness_to_pay":"Hypothèse : 20–40 € par équipe"},{"segment":"Services jeunesse, sport et politique de la ville des communes","role":"organisateur","motivation":"Animation nocturne sans plainte de voisinage","willingness_to_pay":"Hypothèse : 8–10 k€ par soirée clé en main (non testée)"},{"segment":"Marques audio, opérateurs télécoms","role":"sponsor","motivation":"Démonstration produit, canal sponsorisé","willingness_to_pay":"Hypothèse : 1–3 k€ par soirée"},{"segment":"Spectateurs déficients visuels","role":"spectateur","motivation":"Suivre un match grâce à un canal d''audiodescription","willingness_to_pay":"gratuit"}],"inspirations":[{"source_event":"Casques silent disco dans des événements sportifs (prestataire)","source_sector":"festival / événementiel","borrowed_logic":"Diffusion sans enceinte, canaux multiples sélectionnables","adaptation":"Canaux dédiés au commentaire, à l''arbitre et à l''audiodescription","source_ref":"S-QUIET-SPORT"},{"source_event":"Retransmission du micro de l''arbitre aux spectateurs (rugby)","source_sector":"rugby","borrowed_logic":"Le spectateur entend les décisions de l''arbitre","adaptation":"Canal arbitre et coach en direct pendant les temps morts","source_ref":"S-WR-REFCOMMS"},{"source_event":"Cécifoot et goalball (silence du public pendant le jeu)","source_sector":"sport paralympique","borrowed_logic":"Le silence comme règle de spectacle","adaptation":"Le silence est la règle du lieu, l''ambiance passe par le casque","source_ref":"S-PARA-SILENT"}]},"format":{"summary":"Soirée de 20 h à 0 h 30. Remise des casques contre caution à l''entrée. 10 à 16 équipes de foot à 5, poules puis élimination directe sur un terrain unique éclairé (city-stade ou terrain de futsal extérieur). Trois canaux : (1) commentaire en direct par deux commentateurs, (2) DJ, (3) arbitre et coach ; canal 4 : audiodescription. La couleur des voyants des casques indique le canal choisi, ce qui crée l''image de l''événement. Arbitrage et horloge de tir signalés par lumières.","rules_summary":"Règlement de foot à 5 loisir (matchs de 2 × 8 min), sauf : coup de sifflet remplacé par signal lumineux et geste de l''arbitre, fin de période signalée par lumière, temps mort de 30 s avec micro du coach diffusé sur le canal 3. Public : encouragements par gestes et lumières recommandés ; aucune sonorisation extérieure.","duration_hours":4.5,"edition_cadence":"série estivale de 4 à 8 soirées par ville","building_blocks":[{"type":"experience_digitale","label":"Casques sans fil multicanaux (3 + audiodescription)","parameters":{"casques":300,"canaux":4}},{"type":"son_lumiere","label":"Arbitrage et chrono lumineux, aucun son extérieur","parameters":{}},{"type":"mise_en_scene","label":"Voyants colorés des casques comme décor vivant","parameters":{}},{"type":"interaction_public","label":"Choix du canal, vote du joueur de la soirée par QR code","parameters":{}},{"type":"regles","label":"Foot à 5 adapté au silence","parameters":{"equipes":14}},{"type":"activation_partenaire","label":"Canal sponsorisé (marque audio)","parameters":{}},{"type":"monetisation","label":"Prestation vendue à la ville, entrée symbolique, sponsor, buvette sans alcool","parameters":{}},{"type":"creation_contenu","label":"Vidéos « ce que vous n''entendez pas » : plan silencieux puis son du casque","parameters":{}}]},"participants":{"unit":"equipe","count":{"prudent":10,"central":14,"ambitieux":16},"team_size":7,"categories":["Open mixte","Féminines si effectif suffisant"]},"audience":{"attendance":{"prudent":150,"central":250,"ambitieux":350},"paying_share":0.8,"avg_dwell_min":120},"venue_requirements":{"setting":"exterieur","min_area_m2":800,"spaces":[{"id":"terrain","type":"aire_de_jeu","label":"City-stade ou terrain de foot à 5 extérieur éclairé"},{"id":"casques","type":"accueil","label":"Stand de remise et de retour des casques"},{"id":"public","type":"tribune","label":"Zone public debout ou gradins","standing":true},{"id":"regie","type":"regie","label":"Régie audio et commentateurs"},{"id":"secours","type":"secours"}],"power_kw":15,"internet":"4G pour le vote ; la diffusion audio est locale (radio)","notes":"Éclairage de jeu suffisant indispensable ; repli intérieur (gymnase proche d''habitations) en cas de pluie."},"budget":{"currency":"EUR","contingency_rate":0.1,"expenses":[{"id":"e-casques","category":"technique","label":"Location de 300 casques et émetteurs (hypothèse ≈ 5 € par casque)","amount":1500,"basis":"fixed","certainty":"hypothese","priority":1},{"id":"e-audio","category":"technique","label":"Technicien audio et DJ","amount":900,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-commentateurs","category":"animation","label":"Deux commentateurs","amount":400,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-eclairage","category":"technique","label":"Éclairage complémentaire de jeu","amount":1200,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-arbitrage","category":"competition","label":"Arbitres et table de marque (foot à 5)","amount":400,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-signaux","category":"materiel","label":"Kit de signaux lumineux (arbitrage, horloge de tir)","amount":500,"basis":"fixed","certainty":"hypothese","priority":1},{"id":"e-securite","category":"securite","label":"Agents de sécurité et poste de secours","amount":1200,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-assurance","category":"assurance","label":"Assurance RC et casse/perte des casques","amount":300,"basis":"fixed","certainty":"estimation","priority":1},{"id":"e-com","category":"communication","label":"Communication","amount":700,"basis":"fixed","certainty":"estimation","priority":2},{"id":"e-coordination","category":"prestation","label":"Format et coordination EVENT LAB","amount":1500,"basis":"fixed","certainty":"hypothese","priority":1},{"id":"e-hygiene","category":"consommables","label":"Protections hygiéniques de casque","amount":0.3,"basis":"per_attendee","certainty":"estimation","priority":1}],"revenues":[{"id":"r-ville","stream":"autre","label":"Prestation clé en main vendue à la ville","unit_amount":9000,"basis":"fixed","certainty":"probable"},{"id":"r-billetterie","stream":"billetterie","label":"Entrée symbolique 3 €","unit_amount":3,"basis":"per_paying_attendee","certainty":"probable"},{"id":"r-sponsor","stream":"sponsoring","label":"Canal sponsorisé (marque audio)","unit_amount":1500,"basis":"fixed","certainty":"hypothetical"},{"id":"r-buvette","stream":"restauration","label":"Buvette sans alcool : 3 € par spectateur, marge 50 %","unit_amount":3,"basis":"per_attendee","margin_rate":0.5,"certainty":"probable"}]},"risks":[{"id":"R1","category":"reglementaire","description":"Le bruit résiduel du public (cris, applaudissements, conversations) dépasse ce que le voisinage tolère : le casque supprime la sonorisation, pas la foule","probability":4,"impact":4,"critical":true,"warning_signs":["plaintes lors du test","riverains aux fenêtres"],"prevention":["choix d''un site à distance minimale des façades","consignes de célébration silencieuse (gestes, lumières)","fin à 0 h 30","information préalable des riverains"],"continuity_plan":"Arrêt de la phase publique à 23 h et fin du tournoi en format réduit ; repli dans un gymnase","owner_role":"coordinateur","status":"ouvert"},{"id":"R2","category":"securite","description":"Rassemblement nocturne de jeunes : tensions, intrusions, sécurité des spectateurs dans un site ouvert","probability":3,"impact":4,"critical":true,"warning_signs":["regroupements hors périmètre","alcool introduit"],"prevention":["périmètre délimité","agents de sécurité dimensionnés par prestataire","médiateurs de la ville","éclairage des abords"],"continuity_plan":"Arrêt de la soirée sur décision du responsable sécurité ; procédure d''évacuation éclairée","owner_role":"responsable sécurité","status":"ouvert"},{"id":"R3","category":"securite","description":"Spectateurs casqués qui n''entendent pas une alerte ou une consigne d''évacuation","probability":2,"impact":5,"critical":true,"warning_signs":[],"prevention":["message d''alerte prioritaire injecté sur tous les canaux","signal lumineux général","mégaphone de secours"],"continuity_plan":"Coupure des canaux et diffusion du message d''évacuation sur tous les canaux + lumières","owner_role":"régie","status":"ouvert"},{"id":"R4","category":"technique","description":"Perte ou casse de casques, interférences radio, batteries","probability":3,"impact":3,"critical":false,"warning_signs":["taux de retour < 95 % à la première soirée"],"prevention":["caution (pièce d''identité ou paiement)","test radio sur site","casques de réserve"],"continuity_plan":"Repli sur un seul canal mixé ; diffusion sur téléphones si réseau suffisant","owner_role":"technicien audio","status":"ouvert"},{"id":"R5","category":"sante","description":"Volume d''écoute excessif au casque pendant plusieurs heures","probability":2,"impact":3,"critical":false,"warning_signs":[],"prevention":["volume maximal limité côté émetteur","pauses d''écoute annoncées"],"continuity_plan":"Réduction générale du niveau d''émission","owner_role":"technicien audio","status":"ouvert"}],"compliance":[{"id":"C1","item":"Occupation du domaine public ou convention d''usage du site, arrêté municipal d''horaires","authority":"Mairie","mandatory":true,"status":"a_verifier"},{"id":"C2","item":"Bruits de voisinage : réglementation applicable au bruit du public la nuit (Code de la santé publique — articles à vérifier)","authority":"Mairie, préfecture","mandatory":true,"status":"a_verifier"},{"id":"C3","item":"Sons amplifiés : vérifier si la réglementation sur les niveaux sonores (décret de 2017 sur les sons amplifiés) s''applique à une diffusion au casque","authority":"ARS / juriste","mandatory":true,"status":"a_verifier"},{"id":"C4","item":"Fréquences radio des émetteurs utilisées dans des bandes libres autorisées","authority":"Fournisseur des casques","mandatory":true,"status":"a_verifier"},{"id":"C5","item":"Dispositif de sécurité et de secours dimensionné par des prestataires agréés ; rassemblement nocturne déclaré","authority":"Mairie, préfecture, association agréée","mandatory":true,"status":"a_verifier"},{"id":"C6","item":"Diffusion de musique : Sacem ; buvette sans alcool : autorisation municipale","authority":"Sacem, mairie","mandatory":true,"status":"a_verifier"},{"id":"C7","item":"Mineurs présents de nuit : autorisation parentale pour les participants mineurs, politique d''accueil des mineurs spectateurs","authority":"Juriste","mandatory":true,"status":"a_verifier"}],"kpis":[{"id":"K1","label":"Plaintes de riverains","phase":"pendant","target":0,"unit":"plaintes","measure":"registre mairie et police municipale"},{"id":"K2","label":"Taux de retour des casques","phase":"pendant","target":98,"unit":"%","measure":"comptage retour"},{"id":"K3","label":"Spectateurs gardant le casque plus de 60 min","phase":"pendant","target":60,"unit":"%","measure":"relevé à la remise/retour"},{"id":"K4","label":"Villes signant une série après une soirée test","phase":"apres","target":1,"unit":"ville","measure":"bon de commande"}],"media":{"viral_moments":["Plan large silencieux d''un but puis même plan avec le son du casque","Foule aux voyants de couleur qui change de canal","Décision de l''arbitre entendue en direct","Temps mort du coach diffusé"],"photo_spots":["Mur de casques lumineux à l''entrée","Terrain éclairé dans la ville endormie"],"channels":["TikTok","Instagram Reels","YouTube Shorts","presse locale"]},"gamification":[{"mechanic":"Vote du joueur de la soirée","target_role":"spectateur","description":"Vote par QR code pendant la finale","fairness_note":"Un vote par casque, gratuit"}],"evaluation":{"type":"previsionnelle","date":"2026-11-24","ratings":{"originalite":{"rating":3.5,"justification":"Entre ancres 3 et 5. Les briques existent séparément (casques multicanaux dans des événements sportifs selon un prestataire, micro de l''arbitre retransmis aux spectateurs au rugby). Aucune compétition conçue entièrement pour le silence (arbitrage lumineux, canaux, audiodescription) n''a été trouvée. Transposition festival → sport cohérente. Recoupement interne avec deux formats nocturnes de basket du porteur (La Veillée, Les Nocturnes) : la différenciation tient au dispositif silencieux, non au fait de jouer la nuit.","evidence":"benchmark_source","improvements":[]},"experience_utilisateur":{"rating":3,"justification":"Ancre 3. Expérience d''écoute choisie et commentée ; contreparties : file d''attente de remise des casques, port prolongé, conversations entre spectateurs gênées.","evidence":"jugement_expert","improvements":["Remise des casques par QR code pré-réservé pour réduire la file"]},"faisabilite_technique":{"rating":3,"justification":"Ancre 3. Matériel disponible en location ; trois points techniques à sécuriser (remise/retour des casques, alerte d''évacuation sur casques, arbitrage sans sifflet), plus l''éclairage de nuit.","evidence":"jugement_expert","improvements":["Répétition technique sur site avec 20 casques"]},"viabilite_economique":{"rating":2,"justification":"Entre ancres 1 et 3. Le calcul §7.1 donne un déficit au central (prestation ville probable mais non signée, sponsor hypothétique). L''équilibre exige une prestation ville d''environ 10 k€ signée. Règle de cohérence du portefeuille : note de base lue sur le résultat §7.1 (ancres), puis décote de 1,5 lorsque la recette principale dépend d''un prix ou d''un acheteur non testé, et de 0,5 supplémentaire en cas de risque d''investissement ou d''utilisation.","evidence":"jugement_expert","improvements":["Vendre une série de soirées pour amortir l''habillage et la coordination"]},"potentiel_mediatique":{"rating":4,"justification":"Entre ancres 3 et 5. Image forte et identifiable (voyants colorés, contraste silence/son), formats verticaux conçus ; pas encore de contenu généré par les participants intégré.","evidence":"jugement_expert","improvements":["Canal enregistré par les spectateurs pour leurs propres vidéos"]},"reproductibilite":{"rating":3.5,"justification":"Entre ancres 3 et 5. Kit loué et règlement adaptable partout ; dépend de commentateurs de qualité.","evidence":"jugement_expert","improvements":[]},"adaptabilite_lieux":{"rating":4,"justification":"Entre ancres 3 et 5. Conçu pour les lieux contraints (cour, toit, city-stade, parvis) et transposable en intérieur ; repli gymnase prévu.","evidence":"jugement_expert","improvements":[]},"accessibilite_inclusion":{"rating":3.5,"justification":"Entre ancres 3 et 5. Canal d''audiodescription conçu dans le format ; le public sourd ou malentendant perd le commentaire, ce qui exige un sous-titrage sur écran non encore prévu.","evidence":"jugement_expert","improvements":["Écran de sous-titrage du commentaire","Interprète LSF pour la finale"]},"potentiel_commercial":{"rating":3,"justification":"Ancre 3. Prestation ville, sponsor de canal, entrée, buvette ; licence possible aux loueurs de casques.","evidence":"jugement_expert","improvements":[]},"responsabilite_environnementale":{"rating":3.5,"justification":"Entre ancres 3 et 5. Réduction de la pollution sonore, matériel loué et réemployé ; batteries et consommables d''hygiène à gérer.","evidence":"jugement_expert","improvements":[]}},"gates":{"securite":{"status":"ok","notes":"R2 et R3 (sécurité, impact ≥ 4) sont traités par prévention ; le dimensionnement relève d''un prestataire agréé. || calcul : Aucun risque sécurité/santé d''impact 5 et de probabilité ≥ 3 sans prévention. Risques sécurité/santé d''impact ≥ 4 suivis : R2, R3. Le dimensionnement des secours et de la jauge relève d''acteurs externes agréés."},"conformite_reglementaire":{"status":"a_verifier","notes":"Point le plus incertain du portefeuille avec cap-12 : bruit du public la nuit. || calcul : 7 point(s) obligatoire(s) à vérifier (C1, C2, C3, C4, C5, C6, C7) ; règle §1.5 appliquée au stade blueprint, le portefeuille servant de porte d''entrée au blueprint."},"risques_critiques":{"status":"ok","notes":"Risques critiques identifiés (R1, R2, R3), tous dotés d''un plan de continuité. || calcul : Risques critiques identifiés (R1, R2, R3), tous dotés d''un plan de continuité."}},"computed":{"score":64,"grade":"C","confidence":0.34,"verdict":"sous_reserve","gains":{"originalite":3.6,"experience_utilisateur":6,"faisabilite_technique":6,"viabilite_economique":9,"potentiel_mediatique":2,"reproductibilite":3,"adaptabilite_lieux":1.6,"accessibilite_inclusion":1.5,"potentiel_commercial":2,"responsabilite_environnementale":1.5},"score_if_plus_one":84}},"hypotheses":["Location casques ≈ 5 € par unité et par soirée : hypothèse à confirmer par devis.","Prix de la prestation vendue à une ville : 9 000 € (hypothèse, aucun acheteur testé).","Le bruit du public restera acceptable avec des consignes : hypothèse critique, non démontrée."],"sources":[{"id":"S-QUIET-SPORT","title":"Sporting Events — Silent Disco","publisher":"Quiet Events (prestataire, déclaratif)","url":"https://www.quietevents.com/collections/sporting-events","accessed_at":"2026-11-24","reliability":"D","verification":"via résultats de recherche"},{"id":"S-QUIET-NOISE","title":"Noise ordinances & silent disco events","publisher":"Quiet Events (prestataire, déclaratif)","url":"https://www.quietevents.com/collections/noise-ordinances-silent-disco-events","accessed_at":"2026-11-24","reliability":"D","verification":"via résultats de recherche ; la page reconnaît que le bruit de la foule et les règles locales s''appliquent toujours"},{"id":"S-USOPEN-SILENT","title":"US Open Fan Week introduces their first Silent Disco Party","publisher":"Quiet Events (blog)","url":"https://www.quietevents.com/blogs/quiet-event