begin;

on conflict (id) do update set type = excluded.type, name = excluded.name, data = excluded.data, updated_at = now();

on conflict (id) do update set domain = excluded.domain, severity = excluded.severity, title = excluded.title, data = excluded.data, updated_at = now();

on conflict (id) do update set name = excluded.name, url = excluded.url, type = excluded.type, verification = excluded.verification, data = excluded.data, updated_at = now();

-- kb_watch_entries : aucune ligne dans le dépôt

on conflict (id) do update set version = excluded.version, name = excluded.name, data = excluded.data, updated_at = now();

commit;
